Here's a clean, user-friendly C++ program that calculates trapezoid area:

```cpp
#include <iostream>
#include <iomanip>
#include <string>

using namespace std;

class TrapezoidCalculator {
private:
    double longerBase;
    double shorterBase;
    double height;
    double area;

public:
    // Setters for input values
    void setLongerBase() {
        cout << "\n--- Trapezoid Area Calculator ---\n";
        cout << "Enter the length of the longer base: ";
        cin >> longerBase;
        while (longerBase <= 0) {
            cout << "Please enter a positive value: ";
            cin >> longerBase;
        }
    }

    void setShorterBase() {
        cout << "\nEnter the length of the shorter base: ";
        cin >> shorterBase;
        while (shorterBase <= 0) {
            cout << "Please enter a positive value: ";
            cin >> shorterBase;
        }
    }

    void setHeight() {
        cout << "\nEnter the height of the trapezoid: ";
        cin >> height;
        while (height <= 0) {
            cout << "Please enter a positive value: ";
            cin >> height;
        }
    }

    // Calculate the area using the formula: A = (a + b) / 2 * h
    void calculateArea() {
        area = (longerBase + shorterBase) / 2.0 * height;
    }

    // Display all results
    void displayResults() {
        cout << "\n=================== RESULTS ===================\n";
        cout << "Entered values:\n";
        cout << "  Longer base (a):  " << fp2(longerBase) << " units\n";
        cout << "  Shorter base (b): " << fp2(shorterBase) << " units\n";
        cout << "  Height (h):       " << fp2(height) << " units\n";
        cout << "  Calculated Area:  " << fp2(area) << " square units\n";
        cout << "================================================\n";
    }

private:
    // Helper function for formatting output
    string fp2(double value) {
        return fixed << setprecision(2) << value;
    }
};

int main() {
    // Object to handle all calculations
    TrapezoidCalculator calculator;

    try {
        // Collect user input
        calculator.setLongerBase();
        calculator.setShorterBase();
        calculator.setHeight();

        // Perform the calculation
        calculator.calculateArea();

        // Display the results
        calculator.displayResults();

        cout << "\nThank you for using the Trapezoid Area Calculator!\n";
        cout << "Feel free to run the program again for another calculation.\n";

    } catch (const string& error) {
        cout << "Error: " << error << endl;
        return 1;
    }

    return 0;
}
```

This program includes several nice features:

• **Input validation** - Ensures only positive values are accepted
• **Clear formatting** - Consistent decimal places and readable output
• **Error handling** - Basic input validation with user-friendly prompts
• **Clean design** - Organized class structure for better maintainability

You can compile and run it with:
```bash
g++ trapezoid.cpp -o trapezoid
./trapezoid
```

